      if(r.value===null||r.value===undefined||r.value==='') return '—';
      return `${fmt(r.value)}${r.implied?' *':''}`;
    }

    const trades=(tlog?.trades||e1.trades||[]).slice(-20).reverse();
    const tradeRows=trades.map(t=>{
